function settings(tab){settingsTab=tab;$('main-controls').hidden=tab!=='base';$('image-settings').hidden=tab!=='image';document.querySelectorAll('[data-settings]').forEach(b=>b.classList.toggle('active',b.dataset.settings===tab));needsRender=true;}
function explain(key){if(['focal','aperture','time','iso','focus'].includes(key)){activeControl=key;mobileUI?.selectControl(key);}if(help[key])$('control-explainer').innerHTML=`<b>${help[key][0]}</b><p>${help[key][1]}</p>`;document.querySelectorAll('#main-controls .control').forEach(el=>el.classList.toggle('is-active',el.querySelector('input').id===activeControl));document.querySelectorAll('[data-control]').forEach(b=>b.classList.toggle('active',b.dataset.control===activeControl));needsRender=true;translateDOM($('control-explainer'));}
