$('body').onchange=()=>{state.body=$('body').value;explain('body');update();};$('cocMode').onchange=()=>{state.cocMode=$('cocMode').value;explain('cocMode');update();};
for(const key of['matchFrame','tripod','stabilization','portrait','grid','zebra','peaking','motion','lampOn','windowsOn','bokehLights'])$(key).onchange=()=>{state[key]=$(key).checked;if(['tripod','stabilization'].includes(key))explain('tripod');update();};
