document.querySelectorAll('[data-ray]').forEach(b=>b.onchange=()=>{let points=[...document.querySelectorAll('[data-ray]:checked')].map(x=>x.dataset.ray);if(!points.length){b.checked=true;points=[b.dataset.ray];}state.rayTargets=points.join(',');update();});
