function page(name){if(name==='lab'){$('library-dialog').close();return;}for(const p of $('library-dialog').querySelectorAll('.page'))p.hidden=p.id!==`page-${name}`;if(!$('library-dialog').open)$('library-dialog').showModal();$('library-dialog').scrollTop=0;requestAnimationFrame(()=>renderLibrary(name));}
