function update(){
 const m=metrics(state),s=m.s;needsRender=true;for(const key of['sensor','body','mode','cocMode','scene'])$(key).value=state[key];$('body').disabled=s.sensor==='phone';$('mode').querySelector('[value=S]').disabled=s.sensor==='phone';
 const automatic={aperture:s.mode==='S'||s.mode==='P'||s.sensor==='phone',time:s.mode==='A'||s.mode==='P',iso:s.autoISO||s.mode==='P',focus:s.autoFocus,wb:s.autoWB};
 for(const d of definitions){const value=s[d.key],el=$(d.key);el.value=d.list?d.list.indexOf(nearest(d.list,value)):value;$(`out-${d.key}`).textContent=d.format(value);el.setAttribute('aria-valuetext',d.format(value));el.disabled=Boolean(automatic[d.key])||(d.key==='comp'&&s.mode==='M'&&!s.autoISO);}
 document.querySelectorAll('[data-auto]').forEach(b=>{const key=b.dataset.auto;b.classList.toggle('active',Boolean(automatic[key]));b.setAttribute('aria-pressed',String(Boolean(automatic[key])));b.disabled=key==='aperture'&&s.sensor==='phone';b.textContent=b.disabled?'fest':key==='focus'?'AF':'Auto';});
 for(const key of['matchFrame','tripod','stabilization','portrait','grid','zebra','peaking','motion','lampOn','windowsOn','bokehLights'])$(key).checked=state[key];$('portrait').disabled=s.sensor!=='phone';
 document.querySelectorAll('[data-focal]').forEach(b=>b.classList.toggle('selected',Math.abs(Number(b.dataset.focal)-s.focal)<.3));document.querySelectorAll('[data-ray]').forEach(b=>b.checked=s.rayTargets.split(',').includes(b.dataset.ray));document.querySelectorAll('[data-motion]').forEach(b=>b.classList.toggle('active',b.dataset.motion===motionTarget));
 $('motion-label').textContent=motionLabels[motionTarget];$('motion-speed').value=state[motionTarget];$('out-motion-speed').textContent=`${state[motionTarget].toFixed(1)} m/s`;
 const distance=actorDistance(s,roomSelected),validTarget=!['camera','lamp'].includes(roomSelected)&&distance>.3;
 $('room-focus').disabled=!validTarget;$('room-focus').textContent=validTarget?`${actors[roomSelected].name} fokussieren`:'Fokussieren';mobileUI?.selectObject(roomSelected);
 const objectBlur=validTarget?m.blurAt(distance)*1000:null;
 $('room-summary').innerHTML=`<span>${actors[roomSelected].name}${roomSelected!=='camera'?` · ${distanceText(distance)}${distance<=.15?' · hinter der Kamera':objectBlur!==null?` · Kreis ${objectBlur.toFixed(0)} µm`:''}`:''}</span><span>${s.autoFocus?'AF':'Fokus'} ${distanceText(s.focus)} · Doppelklick fokussiert</span>`;
 $('auto-setup').textContent=autoActive()?'Automatik aus':'Automatik ein';$('auto-setup').setAttribute('aria-pressed',String(autoActive()));$('auto-setup').title=autoActive()?'Alle Automatiken beenden; aktuelle Werte beibehalten':'Belichtung, Fokus und Weißabgleich automatisch nachführen';
 $('lampType').value=s.lampType;$('lampType').disabled=!s.lampOn;$('lamp-angle-field').hidden=s.lampType!=='spot';$('lampAngle').value=s.lampAngle;$('out-lampAngle').textContent=`${s.lampAngle}°`;$('lampAngle').disabled=!s.lampOn;
 $('lampEV').value=s.lampEV;$('lampEV').disabled=!s.lampOn;$('out-lampEV').textContent=`${s.lampEV.toFixed(1)} EV`;
 $('photo-settings').innerHTML=`<span>${s.mode}</span><span>ƒ/${Number(s.aperture.toFixed(1))}</span><span>${shutterText(s.time)}</span><span>ISO ${Math.round(s.iso)}</span><span>${Number(s.focal.toFixed(1))} mm</span>`;
 $('photo-help').textContent=s.zebra?'Zebra-Warnung: Rot schraffiert = abgeschnittene Lichter.':s.motion?'Bewegung läuft. Abspielen ausschalten = Bild anhalten.':'Bild anklicken: fokussieren. Abspielen startet die bewegte Vorschau.';
 $('metrics').innerHTML=`<div title="Abweichung für das Umgebungslicht. Bei Lampenmessung kann das Motiv trotzdem korrekt belichtet sein." class="metric ${Math.abs(m.offset)>1?'warn':''}"><div class="label">EV · UMGEBUNG</div><div class="value">${m.offset>=0?'+':''}${m.offset.toFixed(1)} EV</div><div class="sub">zur Szenenreferenz</div></div><div class="metric teal"><div class="label">SCHARF ERSCHEINEND</div><div class="value">${distanceText(m.near)} – ${distanceText(m.far)}</div><div class="sub">c = ${(m.coc*1000).toFixed(1)} µm</div></div><div class="metric"><div class="label">BILDWINKEL</div><div class="value">${m.fov.toFixed(1)}°</div><div class="sub">${m.equivalent.toFixed(0)} mm KB-äquivalent</div></div><div class="metric"><div class="label">LICHT / FLÄCHE</div><div class="value">${m.physical.toFixed(m.physical<.1?3:2)}×</div><div class="sub">Signalverstärkung ${(s.iso/100).toFixed(1)}×</div></div>`;
 const captions={focal:'Die Linsengruppen bestimmen den Bildwinkel. Die Motivpunkte zeigen Lichtwege aus verschiedenen Entfernungen.',aperture:'Die mechanische Blende begrenzt den Strahlenkegel. Die vergrößerte Fokuslage zeigt, ob die Strahlen vor, auf oder hinter dem Sensor zusammentreffen.',focus:`${s.autoFocus?'AF folgt '+actors[s.afTarget].name:'Manueller Fokus'}: ${distanceText(s.focus)}. Im Schema verschiebt sich die hintere Linsengruppe relativ zum Sensor. Die vergrößerte Fokuslage zeigt den Schnittpunkt davor oder dahinter.`,time:`Der Verschluss lässt Licht für ${shutterText(s.time)} durch. Die Zeit ändert die Dauer, nicht die Blendenöffnung.`,iso:`ISO ${Math.round(s.iso)} verstärkt nach dem Sensor. Die Lichtwege bleiben gleich; weniger gesammeltes Licht macht Körnung deutlicher.`};
 $('camera-caption').textContent=captions[activeControl];
 $('insight').innerHTML=Math.abs(m.offset+meteredEV(s)-s.ev-s.comp)>.3&&(s.mode!=='M'||s.autoISO)?'<span class="warning">Automatikgrenze erreicht: Licht, ND oder Vorgaben anpassen.</span>':Math.abs(m.offset)>1.5&&s.mode==='M'&&!s.autoISO?'<span class="warning">Belichtung weit vom Referenzwert. „Automatik ein“ gleicht die Belichtung aus.</span>':s.lampOn?'Lampe im Raum ziehen. Automatik misst das gewählte Motiv; EV zeigt die Umgebung.':'Tempo 0 = still. Zeit und Tempo bestimmen die Spur; Abspielen steuert nur den Ablauf.';
 const sceneLocked=Boolean(activeLesson);document.querySelector('.scene-panel').classList.toggle('scene-locked',sceneLocked);document.querySelector('.scene-lock-hint').hidden=!sceneLocked;document.querySelectorAll('.scene-panel input,.scene-panel select,.scene-panel button').forEach(el=>{el.disabled=sceneLocked||(el.id==='lampEV'||el.id==='lampType'||el.id==='lampAngle')&&!s.lampOn;});
 document.querySelector('.lab-layout').classList.toggle('is-learning',sceneLocked);$('snapshot').hidden=sceneLocked;$('compare').disabled=sceneLocked?false:!saved;$('compare').textContent=sceneLocked?'Original vergleichen':'A/B vergleichen';
 renderChallenge();
 $('lesson-current').hidden=!activeLesson;if(activeLesson){$('lesson-current').textContent=`Versuch ${activeLesson.n}${activeLesson.check(s,m)?' ✓':''}`;$('lesson-current').title=activeLesson.goal;}
 translateDOM();opticsUI?.update();guideUI?.update();
}
function toast(t){$('toast').textContent=t;translateDOM($('toast'));$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
$('reset').onclick=()=>{state={...defaults};simTime=0;motionTarget='ballSpeed';roomSelected='person';activeLesson=null;settings('base');history.replaceState(null,'',location.href.split('#')[0]);explain('aperture');update();toast('Ausgangseinstellungen wiederhergestellt.');};
function shareURL(){const url=new URL(location.href);url.hash=$('share-state').checked?'s='+encodeState(state):'';if(getLanguage()==='en')url.searchParams.set('lang','en');else url.searchParams.delete('lang');return url.href;}
function renderShare(){const url=shareURL();$('share-url').value=url;try{const qr=qrcode(0,'M');qr.addData(url);qr.make();$('share-qr').innerHTML=qr.createSvgTag({cellSize:6,margin:24,scalable:true});}catch{$('share-qr').textContent='Diese Konfiguration ist für einen QR-Code zu lang. Nutzen Sie den Link.';}}
$('share').onclick=()=>{renderShare();$('share-dialog').showModal();};$('share-state').onchange=renderShare;
$('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(shareURL());toast('Link kopiert.');}catch{$('share-url').select();toast('Link markieren und mit Strg/Cmd+C kopieren.');}};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement||document.webkitFullscreenElement){if(document.exitFullscreen)await document.exitFullscreen();else document.webkitExitFullscreen?.();}else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(document.documentElement.webkitRequestFullscreen)document.documentElement.webkitRequestFullscreen();else toast('Vollbild bitte über das Browsermenü öffnen.');}catch(error){$('fullscreen').dataset.error=error.name+': '+error.message;toast('Vollbild ist hier gesperrt. Nutzen Sie das Browsermenü.');}};
