function shortSettings(raw){const {s,sensor}=metrics(raw);return `${sensor.name} · ${Number(s.focal.toFixed(1))} mm · ƒ/${Number(s.aperture.toFixed(1))} · ${shutterText(s.time)} · ISO ${Math.round(s.iso)}`;}
async function drawSavedImage(cv,url){const img=new Image();img.src=url;await img.decode();const ctx=cv.getContext('2d'),ratio=Math.min(cv.width/img.naturalWidth,cv.height/img.naturalHeight),w=img.naturalWidth*ratio,h=img.naturalHeight*ratio;ctx.fillStyle='#e7ebdf';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(img,(cv.width-w)/2,(cv.height-h)/2,w,h);}
function showComparison(a,b,timeA=0,timeB=timeA,labels=['A','B'],images=null){$('compare-dialog').querySelector('p.micro').textContent=timeA===timeB?'Gleicher Bewegungszeitpunkt für den Vergleich der Einstellungen.':'Gespeicherte Aufnahmen mit ihren jeweiligen Bewegungsphasen.';$('compare-dialog').showModal();requestAnimationFrame(()=>{if(images){Promise.all([drawSavedImage($('compare-a'),images[0]),drawSavedImage($('compare-b'),images[1])]).catch(()=>toast('Gespeicherte Aufnahme konnte nicht geladen werden.'));}else{drawPhoto($('compare-a'),a,timeA,{clean:true});drawPhoto($('compare-b'),b,timeB,{clean:true});}});$('compare-a-caption').innerHTML='<strong>'+labels[0]+'</strong><br>'+shortSettings(a);$('compare-b-caption').innerHTML='<strong>'+labels[1]+'</strong><br>'+shortSettings(b);const rows=comparisonRows(a,b);$('compare-diff').innerHTML=rows.length?`<h3>Unterschiedliche Werte</h3><table><thead><tr><th>Parameter</th><th>A</th><th>B</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${r.key}</th><td>${r.a}</td><td class="changed">${r.b}</td></tr>`).join('')}</tbody></table>`:'<p>Die Einstellungen sind gleich.</p>';translateDOM($('compare-dialog'));}
$('compare').onclick=()=>activeLesson?showComparison(lessonOriginal,state,simTime,simTime,['Original','Aktuell']):saved&&showComparison(saved,state,simTime);
function renderLibrary(name){if(name==='learn'){document.querySelectorAll('[data-experiment]').forEach(b=>b.textContent=completedLessons.has(b.dataset.experiment)?'✓ Erneut starten ↗':'Aufgabe starten ↗');}if(name==='learn')for(const el of document.querySelectorAll('[data-lesson-preview]')){const lesson=lessons.find(l=>l.id===el.dataset.lessonPreview);drawPhoto(el,{...defaults,...lesson.setup,motion:false},0,{clean:true});}if(name==='atlas')for(const el of document.querySelectorAll('[data-atlas-preview]')){const id=el.dataset.atlasPreview,raw=atlasState(id,atlasFraming),m=metrics(raw);drawPhoto(el,raw,0,{clean:true});document.querySelector(`[data-atlas-caption="${id}"]`).textContent=`${m.s.focal.toFixed(1)} mm · ƒ/${m.s.aperture} · ${shutterText(m.s.time)} · ISO ${Math.round(m.s.iso)}`;}}
function openLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;state={...defaults,...l.setup};lessonOriginal=structuredClone(state);lessonTime=0;simTime=0;activeLesson=l;challengeStatus='';roomSelected='person';page('lab');settings('base');explain(l.id==='iso'?'iso':'aperture');update();}
function renderChallenge(){const box=$('active-experiment');box.hidden=!activeLesson;mobileUI?.lessonChanged(activeLesson);$('control-explainer').hidden=Boolean(activeLesson);if(!activeLesson)return;
 const m=metrics(state),s=m.s,done=activeLesson.check(s,m),index=lessons.indexOf(activeLesson);
 if(done&&!completedLessons.has(activeLesson.id)){completedLessons.add(activeLesson.id);try{localStorage.setItem('camera.lessons.v1',JSON.stringify([...completedLessons]));}catch{}}
 const already=completedLessons.has(activeLesson.id);box.classList.toggle('completed',done);let diagnostics='';
 if(activeLesson.id==='crop')diagnostics=`Bildwinkel: ${m.fov.toFixed(1)}° · Ziel: 39,6°`;
 if(activeLesson.id==='perspective'){const percent=(s.focal/m.sensor.h/(s.subject+s.cameraBack))/(35/24/5)*100;diagnostics=`Personengröße: ${percent.toFixed(0)} % des Originals · Ziel: 90–110 %`;}
 box.innerHTML=`<div class="learning-heading"><span>Lernmodus · ${index+1} / ${lessons.length}</span><button id="end-task" title="Aufgabe beenden" aria-label="Aufgabe beenden">×</button></div><b>${activeLesson.title}</b><p>${activeLesson.goal}</p>${diagnostics?`<p class="task-diagnostics">${diagnostics}</p>`:''}<p class="task-result" role="status">${done?'✓ Lektion abgeschlossen':already?'Abgeschlossen · weiter experimentieren':'Ziel noch nicht erreicht'}</p><div class="task-buttons"><button id="check-task">Prüfen</button><button id="hint-task">Hinweis</button><button id="solution-task">Lösung</button>${already&&index<lessons.length-1?'<button id="next-task" class="primary">Nächste Aufgabe →</button>':''}</div>${challengeStatus?`<p class="task-status">${challengeStatus}</p>`:''}`;
 $('check-task').onclick=()=>{challengeStatus=done?'Ziel erreicht. Vergleichen Sie Original und aktuelle Aufnahme.':activeLesson.goal;renderChallenge();};$('hint-task').onclick=()=>{challengeStatus=activeLesson.steps.join(' ');renderChallenge();};$('solution-task').onclick=()=>{Object.assign(state,activeLesson.solution);challengeStatus=activeLesson.answer;update();};$('end-task').onclick=()=>{activeLesson=null;lessonOriginal=null;update();};if($('next-task'))$('next-task').onclick=()=>openLesson(lessons[index+1].id);translateDOM(box);
}
$('lesson-current').onclick=()=>{if(activeLesson){$('active-experiment').scrollIntoView({block:'nearest'});$('check-task').focus({preventScroll:true});}};
function galleryHTML(){gallerySelection=new Set([...gallerySelection].filter(id=>photos.some(p=>p.id===id)));$('gallery-count').textContent=`${photos.length} / 20 Fotos · nur in diesem Browser`;$('gallery-compare').disabled=gallerySelection.size!==2;$('gallery-grid').innerHTML=photos.length?photos.slice().reverse().map(p=>`<article class="gallery-card"><img src="${p.image}" alt="Gespeicherte Aufnahme"><div class="gallery-card-title"><label><input type="checkbox" data-gallery-select="${p.id}" ${gallerySelection.has(p.id)?'checked':''}> Vergleichen</label><time>${new Date(p.created).toLocaleString(getLanguage()==='en'?'en-GB':'de-DE',{dateStyle:'short',timeStyle:'short'})}</time></div><p>${shortSettings(p.state)}</p><details><summary>Aufnahmedaten</summary><dl>${stateRows(p.state).map(([key,value])=>`<dt>${key}</dt><dd>${value}</dd>`).join('')}</dl></details><div class="gallery-buttons"><button data-gallery-load="${p.id}">Einstellungen laden</button><button data-gallery-export="${p.id}">PNG</button><button data-gallery-delete="${p.id}" aria-label="Aufnahme löschen">×</button></div></article>`).join(''):'<p>Noch keine Aufnahmen. Im Aufnahmebild auf „Foto“ klicken.</p>';translateDOM($('gallery-dialog'));}
function persistPhotos(next){try{writeGallery(localStorage,next);photos=next;return true;}catch(e){toast(e.name==='QuotaExceededError'?'Browserspeicher voll. Exportieren und löschen Sie ältere Fotos.':e.message||'Speichern ist in diesem Browser nicht verfügbar.');return false;}}
$('take-photo').onclick=()=>{const cv=document.createElement('canvas'),m=metrics(state);cv.width=760;cv.height=Math.round(760*m.sensor.h/m.sensor.w);drawPhoto(cv,{...state,motion:false},simTime,{clean:true});const photo={id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),created:Date.now(),time:simTime,state:structuredClone(state),image:cv.toDataURL('image/jpeg',.85)};if(persistPhotos([...photos,photo]))toast('Foto in der lokalen Galerie gespeichert.');};
$('gallery-open').onclick=()=>{galleryHTML();$('gallery-dialog').showModal();};
$('gallery-grid').onchange=e=>{const id=e.target.dataset.gallerySelect;if(!id)return;e.target.checked?gallerySelection.add(id):gallerySelection.delete(id);$('gallery-compare').disabled=gallerySelection.size!==2;};
$('gallery-grid').onclick=e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.galleryLoad||b.dataset.galleryExport||b.dataset.galleryDelete,p=photos.find(p=>p.id===id);if(!p)return;if(b.dataset.galleryLoad){state=structuredClone(p.state);simTime=p.time;state.motion=false;activeLesson=null;update();$('gallery-dialog').close();toast('Aufnahmeeinstellungen geladen.');}else if(b.dataset.galleryDelete){if(persistPhotos(photos.filter(x=>x.id!==id)))galleryHTML();}else{const img=new Image();img.src=p.image;img.decode().then(()=>{const cv=document.createElement('canvas');cv.width=img.naturalWidth;cv.height=img.naturalHeight;cv.getContext('2d').drawImage(img,0,0);cv.toBlob(blob=>{if(!blob)return;const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='kamera-aufnahme-'+id+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);});}).catch(()=>toast('Gespeicherte Aufnahme konnte nicht geladen werden.'));}};
$('gallery-backup-export').onclick=()=>{const blob=new Blob([exportGallery(photos)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='kamera-galerie.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);};
$('gallery-backup-import').onclick=()=>$('gallery-import-file').click();
$('gallery-import-file').onchange=async()=>{const file=$('gallery-import-file').files[0];if(!file)return;try{if(file.size>18000000)throw new Error('Die Galerie-Datei ist zu groß.');const next=importGallery(await file.text(),photos);if(persistPhotos(next)){galleryHTML();toast('Galerie importiert.');}}catch{toast('Galerie konnte nicht importiert werden. Bitte eine gültige Sicherung mit höchstens 20 Aufnahmen wählen.');}$('gallery-import-file').value='';};
$('gallery-compare').onclick=()=>{if(gallerySelection.size!==2)return;const [a,b]=[...gallerySelection].map(id=>photos.find(p=>p.id===id));showComparison(a.state,b.state,a.time,b.time,['A','B'],[a.image,b.image]);};
function fitWorkspace(){needsRender=true;const scale=document.documentElement.dataset.layout==='mobile'?1:Math.min(1,innerWidth/1120,innerHeight/700);document.documentElement.style.setProperty('--workspace-scale',scale);document.documentElement.style.setProperty('--workspace-height',`${innerHeight/scale}px`);requestAnimationFrame(resize);}
window.addEventListener('resize',fitWorkspace);fitWorkspace();
function resize(){let changed=false;for(const cv of[canvas,cameraCanvas,spaceCanvas]){const r=cv.getBoundingClientRect();if(!r.width||!r.height)continue;const d=Math.min(devicePixelRatio||1,1.5),w=Math.round(r.width*d),h=Math.round(r.height*d);if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;needsRender=true;changed=true;}}if(changed){render(simTime);needsRender=false;}}
for(const cv of[canvas,cameraCanvas,spaceCanvas])new ResizeObserver(resize).observe(cv);
function point(cv,e){const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*cv.width/r.width,y:(e.clientY-r.top)*cv.height/r.height};}
canvas.addEventListener('pointerdown',e=>{if(!photoHit)return;const p=point(canvas,e),id=photoHit.pickAt?.(p.x,p.y);if(id)focusActor(id);});
function roomHit(p){const radius=mobileUI?.active?25*spaceCanvas.width/spaceCanvas.getBoundingClientRect().width:25;return spaceHit?.hits.map(h=>({...h,distance:Math.hypot(h.x-p.x,h.y-p.y)})).filter(h=>h.distance<radius).sort((a,b)=>a.distance-b.distance)[0];}
spaceCanvas.addEventListener('pointerdown',e=>{if(!spaceHit)return;const p=point(spaceCanvas,e),hit=roomHit(p);if(hit){roomSelected=hit.id;const a=actors[hit.id];if(activeLesson&&!(activeLesson.id==='perspective'&&hit.id==='camera')){update();return;}drag={id:hit.id,start:p,z:hit.id==='camera'?-state.cameraBack:state[a.z],x:a.x?state[a.x]:0,scale:spaceHit.scale,sideScale:spaceHit.sideScale,bounds:{minZ:spaceHit.minZ,maxZ:spaceHit.maxZ,sideScale:spaceHit.sideScale}};spaceCanvas.setPointerCapture(e.pointerId);update();}else{state.focus=clamp((p.x-spaceHit.margin)/spaceHit.scale+spaceHit.minZ+state.cameraBack,.3,150);state.autoFocus=false;explain('focus');update();}});
spaceCanvas.addEventListener('pointermove',e=>{const p=point(spaceCanvas,e);if(!drag){const target=roomHit(p);spaceCanvas.title=target?actors[target.id].name+' · '+distanceText(actorDistance(state,target.id)):'Doppelklick fokussiert';spaceCanvas.style.cursor=spaceHit?.hits.some(h=>Math.hypot(h.x-p.x,h.y-p.y)<25)?'grab':'crosshair';return;}state=moveActor(state,drag.id,drag.z+(p.x-drag.start.x)/drag.scale,drag.x+(p.y-drag.start.y)/drag.sideScale);update();});
spaceCanvas.addEventListener('dblclick',e=>{const p=point(spaceCanvas,e),hit=roomHit(p);if(hit)focusActor(hit.id);});
for(const event of['pointerup','pointercancel'])spaceCanvas.addEventListener(event,()=>{drag=null;needsRender=true;});
cameraCanvas.addEventListener('pointerdown',e=>{if(!cameraHit)return;const p=point(cameraCanvas,e),hit=cameraHit.parts.find(h=>Math.abs(p.x-h.x)<h.w/2&&Math.abs(p.y-h.y)<h.h/2);if(hit){selectControl(hit.key);cameraDrag={key:hit.key,x:e.clientX,y:e.clientY,value:effective(state)[hit.key],moved:false};cameraCanvas.setPointerCapture(e.pointerId);}});
cameraCanvas.addEventListener('pointermove',e=>{if(cameraDrag){const dx=e.clientX-cameraDrag.x,dy=e.clientY-cameraDrag.y;if(Math.hypot(dx,dy)>4)cameraDrag.moved=true;if(cameraDrag.moved)editCameraParameter(cameraDrag.key,diagramDragValue(cameraDrag.key,cameraDrag.value,dx,dy));return;}const p=point(cameraCanvas,e),hit=cameraHit?.parts.find(h=>Math.abs(p.x-h.x)<h.w/2&&Math.abs(p.y-h.y)<h.h/2),next=hit?.key||null;cameraCanvas.style.cursor=next?['focal','focus'].includes(next)?'ew-resize':'ns-resize':'default';if(next!==hoveredControl){hoveredControl=next;needsRender=true;}});
for(const event of['pointerup','pointercancel'])cameraCanvas.addEventListener(event,()=>cameraDrag=null);
cameraCanvas.addEventListener('dblclick',()=>opticsUI?.open(activeControl==='time'?'shutter':'aperture'));
cameraCanvas.addEventListener('pointerleave',()=>{hoveredControl=null;needsRender=true;});
function render(t,onlyPhoto=false){if(opticsUI?.isOpen)return;const signature=JSON.stringify(state)+'|'+t+'|'+canvas.width+'x'+canvas.height+'|'+getLanguage();if(signature!==photoSignature){photoHit=drawPhoto(canvas,state,t,{fast:guideUI?.demoPlaying});photoSignature=signature;}if(!onlyPhoto){if(cameraCanvas.getBoundingClientRect().width)cameraHit=drawCutaway(cameraCanvas,state,{active:activeControl,hovered:hoveredControl});if(spaceCanvas.getBoundingClientRect().width)spaceHit=drawRoom(spaceCanvas,state,{selected:roomSelected,bounds:drag?.bounds});}}
function animate(now){const dt=Math.min((now-lastTick)/1000,.1);lastTick=now;const moving=state.motion&&!document.hidden;if(moving)simTime+=dt;if(needsRender||(moving&&now-lastTime>30)){render(simTime,!needsRender);needsRender=false;lastTime=now;}requestAnimationFrame(animate);}
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';$('theme-toggle').setAttribute('aria-pressed',String(dark));$('theme-icon').textContent=dark?'☀':'☾';needsRender=true;}
$('theme-toggle').onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('camera.theme.v1',next);}catch{}syncTheme();};
syncTheme();
$('language').value=getLanguage();$('language').onchange=()=>setLanguage($('language').value);document.addEventListener('camera-language-change',()=>{update();explain(activeControl);needsRender=true;});
mobileUI=initMobile({onResize:fitWorkspace,onControl:selectControl,onSettings:settings,onRoomSelect:id=>{roomSelected=id;update();}});
function editCameraParameter(key,value){if(key==='aperture'&&state.sensor==='phone')return;const mode=state.mode;if((key==='aperture'&&['S','P'].includes(mode))||(key==='time'&&['A','P'].includes(mode))){adopt();state.mode=key==='aperture'?'A':'S';}if(key==='iso'){if(mode==='P'){adopt();state.mode='M';}state.autoISO=false;}if(key==='focus')state.autoFocus=false;state[key]=value;explain(key);update();}
function learningChange(patch){if('aperture' in patch&&state.sensor==='phone')return;if('mode' in patch)adopt();if('aperture' in patch&&['S','P'].includes(state.mode)){adopt();state.mode='A';}if('focus' in patch&&!('autoFocus' in patch))state.autoFocus=false;Object.assign(state,patch);update();}
opticsUI=createOptics({state:()=>state,time:()=>simTime,moving:()=>state.motion,animating:()=>guideUI?.demoPlaying,change:learningChange,replace:(raw,resetTime=true)=>{state={...raw};if(resetTime)simTime=0;update();},focus:focusActor,comparisonA:()=>saved,remember:raw=>{saved=structuredClone(raw);update();},compare:(a,b)=>showComparison(a,b,simTime,simTime),onClose:()=>{needsRender=true;guideUI?.opticsClosed();}});
const deepen=document.createElement('button');deepen.id='optics-open';deepen.className='quiet';deepen.textContent='◎ Optik';deepen.title='Blende, Lichtpunkte und Verschluss vertiefen';document.querySelector('.camera-panel .panel-title').append(deepen);deepen.onclick=()=>opticsUI.open(activeControl==='time'?'shutter':'aperture');
const mobileDeepen=document.createElement('button');mobileDeepen.className='optics-mobile-entry';mobileDeepen.textContent='◎ Optiklabor';document.getElementById('mobile-panel-camera').append(mobileDeepen);mobileDeepen.onclick=()=>opticsUI.open(activeControl==='time'?'shutter':'aperture');
function guideTarget(key,detail,step){if(detail){const id=detail==='shutter'?'opt-time':step?.id==='pupil'?'opt-shape':'opt-N';return {element:document.getElementById(id)};}if(step?.id==='dolly'){const h=spaceHit?.hits.find(h=>h.id==='camera');return {element:spaceCanvas,fx:h?h.x/spaceCanvas.width:.5,fy:h?h.y/spaceCanvas.height:.5};}const element=$(key);if(!element)return null;if(element.type==='range')return {element,fx:.04+.92*(Number(element.value)-Number(element.min))/(Number(element.max)-Number(element.min)),fy:.5};return {element};}
guideUI=createGuide({closeAuxiliary:()=>{for(const dialog of document.querySelectorAll('dialog[open]'))dialog.close();},state:()=>state,replace:(raw,resetTime=true)=>{state={...raw};if(resetTime)simTime=0;update();},change:learningChange,snapshot:()=>structuredClone({state,simTime,saved,activeLessonId:activeLesson?.id,lessonOriginal,lessonTime,activeControl,settingsTab,motionTarget,roomSelected}),restore:backup=>{state=backup.state;simTime=backup.simTime;saved=backup.saved;activeLesson=lessons.find(l=>l.id===backup.activeLessonId)||null;lessonOriginal=backup.lessonOriginal;lessonTime=backup.lessonTime;motionTarget=backup.motionTarget;roomSelected=backup.roomSelected;settings(backup.settingsTab);explain(backup.activeControl);update();},suspendLesson:()=>{activeLesson=null;lessonOriginal=null;},remember:raw=>{saved=structuredClone(raw);},show:step=>{settings('base');if(['focal','aperture','focus','time','iso'].includes(step.target))selectControl(step.target);else explain('iso');mobileUI.showArea(step.view==='camera'||step.view==='optics'?'camera':step.view==='room'?'room':'controls');},target:guideTarget,highlight:(key,detail)=>{document.querySelectorAll('.guide-highlight').forEach(el=>el.classList.remove('guide-highlight'));if(!key)return;const target=guideTarget(key,detail,detail?{id:detail==='aperture'?'pupil':'curtains'}:null)?.element;if(target){(target.closest('.control,.optic-field')||target).classList.add('guide-highlight');if(document.documentElement.dataset.layout==='mobile')target.scrollIntoView({block:'nearest',behavior:'instant'});}}},opticsUI);
explain('aperture');update();resize();translateDOM();requestAnimationFrame(animate);
